from datetime import datetime, timedelta
import re

def next_run(cron_expr: str) -> datetime:
    # Simplified parser for standard 5-part cron
    parts = cron_expr.split()
    if len(parts) != 5: raise ValueError("Invalid cron format")

    minute, hour, day, month, weekday = parts
    now = datetime.now()

    # Helper to check match
    def match(part, val):
        if part == '*': return True
        if ',' in part: return str(val) in part.split(',')
        if '/' in part:
            base, step = part.split('/')
            return (val - (0 if base == '*' else int(base))) % int(step) == 0
        return str(val) == part

    # Iterate forward (max 4 years lookahead)
    for _ in range(1461): 
        if match(month, now.month) and match(weekday, now.weekday()) and match(day, now.day):
            if match(hour, now.hour) and match(minute, now.minute):
                if now > datetime.now(): return now
        now += timedelta(minutes=1)
    raise ValueError("No match found")
